begin;
create temp table _truoc as select count(*) n from public.question_bank;
insert into public.question_bank (subject_code, grade, topic_id, topic_name, form, qtype, difficulty, difficulty_source, question, content_hash, archived, note)
select 'vat-ly', '12', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl12-c2-20261024'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong thí nghiệm Brown (do nhà bác học Brown, người Anh thực hiện năm 1827) người ta quan sát được:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong thí nghiệm Brown, thứ quan sát được trực tiếp dưới kính hiển vi là các hạt phấn hoa lơ lửng trong nước, chúng chuyển động hỗn độn không ngừng.</p><p class=\"text-base leading-relaxed my-2\">Phân tử, nguyên tử nước quá nhỏ nên không nhìn thấy trực tiếp; chúng chỉ là nguyên nhân gây ra chuyển động đó.</p>","options":["Các phân tử nước chuyển động hỗn độn không ngừng về mọi phía.","Các nguyên tử nước chuyển động hỗn độn không ngừng về mọi phía.","Các hạt phấn hoa chuyển động hỗn độn không ngừng về mọi phía.","Các phân tử và nguyên tử nước chuyển động hỗn độn không ngừng về mọi phía."],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động của các hạt phấn hoa trong thí nghiệm của Brown là chuyển động gì?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các hạt phấn hoa bị các phân tử nước va chạm từ nhiều phía với lực không cân bằng nên chuyển động hỗn độn (quỹ đạo gấp khúc, không theo quy luật).</p>","options":["Chuyển động đều","Chuyển động định hướng","Chuyển động tròn","Chuyển động hỗn độn"],"answer":3}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhà bác học nào sau đây là người đầu tiên giải thích đầy đủ về chuyển động của hạt phấn hoa trong thí nghiệm của Brown</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động Brown được An-be Anh-xtanh (Einstein) giải thích đầy đủ năm 1905 bằng thuyết động học phân tử. Brown chỉ là người quan sát hiện tượng.</p>","options":["Ixac Niuton","Galilê","Brown","An-be Anh-xtanh"],"answer":3}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hạt phấn hoa chuyển động không ngừng trong nước về mọi phía trong chuyển động Brown là do:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các phân tử nước chuyển động nhiệt hỗn độn, va chạm liên tục vào hạt phấn hoa từ mọi phía. Lực tổng hợp lên hạt thay đổi ngẫu nhiên nên hạt chuyển động hỗn độn.</p><p class=\"text-base leading-relaxed my-2\">Hạt phấn hoa tự nó không chuyển động hỗn độn vì lí do nội tại, nên các phương án A, C, D sai.</p>","options":["nguyên tử phấn hoa chuyển động hỗn độn không ngừng.","phân tử nước chuyển động hỗn độn không ngừng va chạm vào các hạt phấn hoa.","phân tử phấn hoa chuyển động hỗn độn không ngừng.","Cả ba lí do trên."],"answer":1}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Động năng trung bình phân tử và nhiệt độ","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy phán đoán xem, trong thí nghiệm Brown, nếu ta tăng nhiệt độ của nước thì các hạt phấn hoa chuyển động như thế nào?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Nhiệt độ nước tăng thì các phân tử nước chuyển động nhiệt nhanh hơn, va chạm mạnh và thường xuyên hơn vào hạt phấn hoa.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Hạt phấn hoa chuyển động nhanh hơn.</p>","options":["Không đoán được","Chuyển động chậm hơn.","Chuyển động nhanh hơn .","Chuyển động không đổi."],"answer":2}$q$::jsonb, 212, $q$Động năng trung bình phân tử và nhiệt độ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động nào kể sau không phải là chuyển động Brown?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động Brown là chuyển động hỗn độn của các hạt nhỏ lơ lửng trong chất lỏng hoặc chất khí (phấn hoa trong nước, khói bụi trong không khí, bụi than trong rượu).</p><p class=\"text-base leading-relaxed my-2\">Chuyển động hỗn loạn của chính các nguyên tử, phân tử là chuyển động nhiệt, không phải chuyển động Brown.</p>","options":["Hạt phấn hoa chuyển động trong nước.","Hạt khói bụi chuyển động trong không khí.","Chuyển động hỗn loạn của nguyên tử, phân tử.","Bụi than chuyển động trong rượu."],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chuyển động nào sau đây là chuyển động Brown?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động Brown là chuyển động hỗn độn của hạt nhỏ lơ lửng trong chất khí hoặc chất lỏng, như hạt bụi nhỏ trong không khí.</p><p class=\"text-base leading-relaxed my-2\">Phương án A là chuyển động nhiệt của phân tử, B là chuyển động có hướng, D là chuyển động rơi có hướng, đều không phải chuyển động Brown.</p>","options":["Chuyển động hỗn loạn không ngừng của các phân tử nước.","Chuyển động có hướng của dòng electron trong dây dẫn điện.","Chuyển động của hạt bụi nhỏ trong không khí.","Chuyển động rơi của quả dừa."],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Giải thích vì sao các hạt bụi nhỏ li ti chuyển động hỗn loạn không ngừng trong không khí?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các phân tử khí chuyển động hỗn loạn va chạm vào hạt bụi từ nhiều phía với lực tổng hợp thay đổi, làm hạt bụi chuyển động hỗn loạn không ngừng (chuyển động Brown).</p><p class=\"text-base leading-relaxed my-2\">Gió hay độ nhẹ của hạt bụi không giải thích được tính hỗn loạn không ngừng này.</p>","options":["Do có gió làm hạt bụi chuyển động","Do hạt bụi nhẹ nên dẽ̃ bay","Do các phân tử khí chuyển động hỗn loạn không ngừng va chạm với các hạt bụi trong quá trình chuyển động làm hạt bụi chuyển động hỗn loạn không ngừng theo","Tất cả đều đúng"],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi xịt nước hoa ở một góc của căn phòng thì ta vẫn ngửi được hương thơm ở một vị trí khác, vì:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phân tử nước hoa ở thể hơi chuyển động hỗn loạn không ngừng, khuếch tán khắp căn phòng nên ở vị trí khác vẫn ngửi được mùi hương.</p>","options":["Quạt máy thổi hương thơm bay xa hơn.","Nồng độ hương thơm trong lọ quá nhiều.","Khi xịt nước hoa ra khỏi lọ, nước hoa sẽ ở thể hơi nên các hạt chuyển động tự do khắp căn phòng. Vì thế, ta ngửi được hương thơm ở khắp nơi trong căn phòng.","Tất cả các ý trên đều sai."],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quỹ đạo của hạt phấn hoa có dạng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hạt phấn hoa bị va chạm ngẫu nhiên nên đổi hướng liên tục: quỹ đạo gấp khúc và không theo quy luật nào.</p>","options":["gấp khúc và theo quy luật","tròn và không theo quy luật","gấp khúc và không theo quy luật","thẳng và không theo quy luật\n<strong>II. Chất khí</strong>\n<strong>1- Tính chất của chất khí</strong>"],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tính chất nào sau đây không phải là của chất khí</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chất khí vẫn được cấu tạo từ các phân tử, nguyên tử. Các phương án A, B, C đều là tính chất của chất khí (chiếm toàn bộ thể tích bình, dễ nén, khối lượng riêng nhỏ).</p>","options":["Chiếm toàn bộ thể tích của bình chứa","Dễ nén","Có khối lượng riêng nhỏ so với chất rắn và chất lỏng","Không được cấu tạo từ các phân tử, nguyên tử"],"answer":3}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tính chất nào sau đây không phải là tính chất của chất khí?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chất khí không có hình dạng và thể tích riêng, mà chiếm toàn bộ thể tích bình chứa. Có hình dạng và thể tích riêng là tính chất của chất rắn.</p>","options":["Có hình dạng và thể tích riêng.","Có các phân tử chuyển động hỗn loạn không ngừng.","Có thể nén được dễ dàng.","Có khối lượng riêng nhỏ so với chất rắn và chất lỏng."],"answer":0}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Mol, số Avogadro và lượng chất khí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tìm câu <strong>sai</strong> trong các câu sau đây: Số A – vô – ga – đrô là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Số A-vô-ga-đrô $N_A=6{,}02\\cdot10^{23}$ là số phân tử (nguyên tử) trong 1 mol chất, tức trong 22,4 lít khí ở điều kiện tiêu chuẩn, hay trong 12 g cacbon 12.</p><p class=\"text-base leading-relaxed my-2\">Nó không phải số phân tử trong một đơn vị khối lượng khí, nên phương án C sai.</p>","options":["số phân tử (hay nguyên tử) có trong 22,4 lít khí ở điều kiện tiêu chuẩn (0$^{o}$C,1*atm*).","số phân tử (hay nguyên tử) có trong 1 mol khí.","số phân tử (hay nguyên tử) có trong 1 đơn vị khối lượng khí.","số nguyên tử có trong 12 g cacbon 12."],"answer":2}$q$::jsonb, 205, $q$Mol, số Avogadro và lượng chất khí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Mol, số Avogadro và lượng chất khí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho khối lượng của chất là m (gam), số mol của chất là n (mol) và khối lượng mol là M (gam/mol). Biểu thức tính số mol là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol bằng khối lượng chia khối lượng mol: $n=\\dfrac{m}{M}$.</p>","options":["n = m. M","n = m/M","n = m + M","n = M/m"],"answer":1}$q$::jsonb, 205, $q$Mol, số Avogadro và lượng chất khí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Mol, số Avogadro và lượng chất khí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Gọi M là khối lượng mol, $N_{A}$ là số Avogadro, m là khối lương của một chất nào đó. Biểu thức xác định số phân tử hay nguyên tử chứa trong khối lượng m của chất đó là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol: $n=\\dfrac{m}{M}$.</p><p class=\"text-base leading-relaxed my-2\">Số phân tử: $N=nN_A$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N=\\dfrac{mN_A}{M}$.</p>","options":["N = $MmN_{A}$","N = $MN_{A}$/m","N = $mN_{A}$/M","N = $N_{A}$/mM"],"answer":2}$q$::jsonb, 205, $q$Mol, số Avogadro và lượng chất khí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Mol, số Avogadro và lượng chất khí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi nói về khối lượng phân tử của chất khí $H_{2}$, He, $O_{2}$ và $N_{2}$ thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khối lượng mol xấp xỉ: $H_2$ là 2 g/mol, He là 4 g/mol, $N_2$ là 28 g/mol, $O_2$ là 32 g/mol.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Phân tử $O_2$ có khối lượng lớn nhất, $H_2$ nhẹ nhất (không phải He).</p>","options":["khối lượng phân tử của các khí $H_{2}$, He, $O_{2}$, $N_{2}$ đều bằng nhau","Khối lượng phân tử của $O_{2}$ nặng nhất trong 4 loại khí trên","Khối lượng phân tử của $N_{2}$ nặng nhất trong 4 loại khí trên","Khối lượng phân tử của He nhẹ nhất trong 4 loại khí trên\n<strong>III. Mô hình động học của các phân tử chất khí</strong>\n<strong>1- Mô hình</strong>"],"answer":1}$q$::jsonb, 205, $q$Mol, số Avogadro và lượng chất khí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Theo thuyết động học phân tử chất khí thì điều nào sau đây là không đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo thuyết động học phân tử, các phân tử chuyển động càng nhanh thì nhiệt độ chất khí càng cao, không phải càng thấp. Các phương án B, C, D đều đúng.</p>","options":["Các phân tử khí chuyển động hỗn loạn không ngừng, chuyển động này càng nhanh thì nhiệt độ của chất khí càng thấp.","Chất khí được cấu tạo từ các phân tử có kích thước rất nhỏ so với khoảng cách giữa chúng.","Khi chuyển động hỗn loạn các phân tử khí va chạm vào thành bình gây ra áp suất lên thành bình.","Khi chuyển động hỗn loạn các phân tử khí va chạm vào nhau."],"answer":0}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ áp suất với động năng phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Áp suất của chất khí lên thành bình chứa là do</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi chuyển động hỗn loạn, các phân tử khí va chạm vào thành bình, mỗi va chạm truyền một xung lực lên thành bình. Tổng hợp rất nhiều va chạm tạo ra áp suất chất khí lên thành bình.</p>","options":["các phân tử chất khí va chạm vào nhau.","các phân tử chất khí đẩy nhau.","các phân tử chất khí va chạm nhau và không va chạm vào thành bình chứa.","khi chuyển động hỗn loạn, các phân tử khí va chạm vào nhau và va chạm vào thành bình chứa."],"answer":3}$q$::jsonb, 211, $q$Liên hệ áp suất với động năng phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hiện tượng nào sau đây không thể hiện rõ thuyết động học phân tử?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Không khí nóng nổi lên, không khí lạnh chìm xuống là đối lưu do chênh lệch khối lượng riêng, không thể hiện rõ chuyển động nhiệt phân tử.</p><p class=\"text-base leading-relaxed my-2\">Các hiện tượng B, C, D (khuếch tán mùi, chuyển động Brown, khuếch tán mực) thể hiện rõ chuyển động hỗn loạn của phân tử.</p>","options":["Không khí nóng thì nổi lên cao, không khí lạnh chìm xuống trong bầu khí quyển","Mùi nước hoa lan toả trong một căn phòng kín.","Chuyển động hỗn loạn của các hạt phấn hoa trong nước yên lặng","Cốc nước được nhỏ mực, sau một thời gian có màu đồng nhất.\n<strong>2- Khí lí tưởng</strong>"],"answer":0}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Điền vào chỗ trống: chất khí trong đó các phân tử được coi là…và chỉ tương tác khi… được gọi là khí lí tưởng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khí lí tưởng: các phân tử được coi là chất điểm (kích thước không đáng kể) và chỉ tương tác với nhau khi va chạm.</p>","options":["chất điểm; va chạm","vật rắn; va chạm","chất điểm; ở gần nhau","vật rắn; ở gần nhau"],"answer":0}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhận xét nào sau đây về các phân tử khí lí tưởng là không đúng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phân tử khí lí tưởng coi là chất điểm (thể tích riêng không đáng kể), lực tương tác chỉ khi va chạm, nhưng vẫn có khối lượng xác định, không phải không đáng kể. Vận tốc tăng khi nhiệt độ tăng.</p>","options":["Có thể tích riêng không đáng kể.","Có lực tương tác không đáng kể khi không va chạm.","Có khối lượng không đáng kể.","Có vận tốc càng lớn khi nhiệt độ phân tử càng cao.\nTài liệu được chia sẻ bởi Website VnTeach.Com\n<https://www.vnteach.com>"],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng nhiệt và định luật Boyle","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Định luật Bôi-lơ - Ma-ri-ốt cho ta biết điều gi?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Bôi-lơ - Ma-ri-ốt: với một lượng khí xác định ở nhiệt độ không đổi, áp suất tỉ lệ nghịch với thể tích, tức liên hệ giữa $p$ và $V$ khi $T$ không đổi.</p>","options":["Liên hệ giữa áp suất và thể tích của một lượng khí khi nhiệt độ không đổi.","Liên hệ giữa áp suất và nhiệt độ của một lượng khí khi thể tích không đổi.","Liên hệ giữa thể tích và nhiệt độ của một lượng khí khi áp suất không đổi.","Liên hệ giữa áp suất, thể tích và nhiệt độ của một lượng khí xác định."],"answer":0}$q$::jsonb, 206, $q$Quá trình đẳng nhiệt và định luật Boyle$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng nhiệt và định luật Boyle","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các hệ thức sau đây hệ thức nào không phù hợp với định luật Bôi-lơ - Ma-ri-ốt?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Bôi-lơ - Ma-ri-ốt: $pV=\\text{const}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow p\\sim\\dfrac1V$, $V\\sim\\dfrac1p$, $p_1V_1=p_2V_2$.</p><p class=\"text-base leading-relaxed my-2\">Hệ thức $V\\sim p$ (tỉ lệ thuận) sai.</p>","options":["𝑝 \\~ $\\frac{1}{V}$ .","𝑉 *\\~* $\\frac{1}{p}$ .","𝑉 \\~ 𝑝.","$𝑝_{1}$$𝑉_{1}$ = $𝑝_{2}$$𝑉_{2}$."],"answer":2}$q$::jsonb, 206, $q$Quá trình đẳng nhiệt và định luật Boyle$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng nhiệt và định luật Boyle","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nhận xét nào sau đây là sai khi nói về quá trình đẳng nhiệt của một lượng khí nhất định</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình đẳng nhiệt của một lượng khí xác định tuân theo định luật Boyle: $pV = \\text{const}$ (nhiệt độ và khối lượng khí không đổi).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$p$ và $V$ tỉ lệ nghịch, tích $pV$ không đổi (A, B, C đúng).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Khi $p$ tăng 2 lần thì $V$ giảm 2 lần, không phải tăng 2 lần. Vậy nhận xét D là sai.</p>","options":["Tích của áp suất và thể tích luôn không đổi.","Áp suất và thể tích tỉ lệ nghịch với nhau.","Khi áp suất khí tăng 2 lần thì tích pV vẫn không đổi.","Khi áp suất khí tăng 2 lần thì thể tích cũng tăng 2 lần."],"answer":3}$q$::jsonb, 206, $q$Quá trình đẳng nhiệt và định luật Boyle$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đọc đồ thị các đẳng quá trình","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu đúng khi nói về đường đẳng nhiệt trong hệ trục tọa độ (pOV).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với $T$ không đổi, $p = \\dfrac{\\text{const}}{V}$ nên đường đẳng nhiệt trong hệ $(p, V)$ là một nhánh hypebol.</p><p class=\"text-base leading-relaxed my-2\">Đường thẳng song song với trục $OV$ là đường đẳng áp; đường thẳng qua gốc tọa độ là dạng của đường đẳng tích trong $(p, T)$ hoặc đẳng áp trong $(V, T)$. Vậy chọn A.</p>","options":["Là một đường cong hypebol biểu diễn mối quan hệ của áp suất vào thể tích của một lượng khí xác định khi nhiệt độ không đổi.","Là đường thẳng song song với trục OV biểu diễn mối quan hệ giữa áp suất và thể tích.","Là đường thẳng kéo dài đi qua gốc tọa độ.","Là đường biểu diễn mối quan hệ giữa thể tích và nhiệt độ."],"answer":0}$q$::jsonb, 208, $q$Đọc đồ thị các đẳng quá trình$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng nhiệt và định luật Boyle","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi ấn pittông từ từ xuống để nén khí trong xilanh, thì thông số nào của khí trong xilanh thay đổi?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ấn pittông từ từ nên nhiệt độ khí coi như không đổi, khối lượng khí không đổi; thể tích giảm.</p><p class=\"text-base leading-relaxed my-2\">Theo định luật Boyle $pV = \\text{const}$ nên $V$ giảm thì $p$ tăng. Vậy áp suất khí tăng.</p>","options":["Nhiệt độ khí giảm","Áp suất khí tăng","Áp suất khí giảm","Khối lượng khí tăng"],"answer":1}$q$::jsonb, 206, $q$Quá trình đẳng nhiệt và định luật Boyle$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Nội dung thuyết động học phân tử","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khí nào sau đây không phải là khí lí tưởng?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khí lí tưởng là khí mà phân tử coi là chất điểm, bỏ qua tương tác (trừ lúc va chạm), và tuân theo đúng các định luật chất khí, trong đó có định luật Boyle - Mariotte.</p><p class=\"text-base leading-relaxed my-2\">Khí không tuân theo đúng định luật Boyle - Mariotte là khí thực, không phải khí lí tưởng. Vậy chọn C.</p>","options":["Khí mà các phân tử được coi là chất điểm.","Khí mà các phân tử chuyển động càng nhanh khi nhiệt độ càng cao.","Khí không tuân theo đúng định luật Bôi-lơ - Ma-ri-ốt.","Khí mà lực tương tác giữa các phân tử khi không va chạm là không đáng kể."],"answer":2}$q$::jsonb, 204, $q$Nội dung thuyết động học phân tử$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng áp và định luật Charles","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu trả lời đúng: Quá trình đẳng áp cho biết hệ thức liên hệ giữa:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình đẳng áp là quá trình biến đổi trạng thái khi áp suất không đổi, theo định luật Charles: $\\dfrac{V}{T} = \\text{const}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy hệ thức liên hệ thể tích và nhiệt độ tuyệt đối khi áp suất không đổi. A là đẳng nhiệt, B là đẳng tích.</p>","options":["Thể tích và áp suất khí khi nhiệt độ không đổi","Áp suất và nhiệt độ tuyệt đối khi thể tích không đổi","Thể tích và nhiệt độ tuyệt đối khi áp suất không đổi","Thể tích, áp suất và nhiệt độ của khí lí tưởng"],"answer":2}$q$::jsonb, 207, $q$Quá trình đẳng áp và định luật Charles$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Quá trình đẳng áp và định luật Charles","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đối với một lượng khí xác định, quá trình nào sau đây là đẳng áp?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đẳng áp: $p$ không đổi, khi đó $\\dfrac{V}{T} = \\text{const}$, tức $V$ tỉ lệ thuận với $T$ (nhiệt độ tuyệt đối).</p><p class=\"text-base leading-relaxed my-2\">A, B có nhiệt độ không đổi là đẳng nhiệt. D sai vì $V$ tăng khi $T$ giảm là tỉ lệ nghịch. Vậy chọn C.</p>","options":["Nhiệt độ không đổi, thể tích tăng.","Nhiệt độ không đổi, thể tích giảm.","Nhiệt độ tăng, thể tích tăng tỉ lệ thuận với nhiệt độ.","Nhiệt độ giảm, thể tích tăng tỉ lệ nghịch với nhiệt độ."],"answer":2}$q$::jsonb, 207, $q$Quá trình đẳng áp và định luật Charles$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đọc đồ thị các đẳng quá trình","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong hệ toạ độ (𝑉, 𝑇), đường biểu diễn nào sau đây là đường đẳng áp?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình đẳng áp: $V = kT$ với $k = \\text{const}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Trong hệ $(V, T)$ đồ thị là đường thẳng kéo dài đi qua gốc tọa độ.</p>","options":["Đường thẳng song song với trục hoành.","Đường thẳng song song với trục tung.","Đường hypebol.","Đường thẳng kéo dài đi qua gốc toạ độ."],"answer":3}$q$::jsonb, 208, $q$Đọc đồ thị các đẳng quá trình$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Động năng trung bình phân tử và nhiệt độ","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Khi thổi bong bóng xà phòng, ta quan sát thấy lúc đầu bong bóng bay lên cao rồi dần dần rơi xuống (nếu bong bóng không vỡ giữa chừng). Hãy giải thích hiện tượng và cho biết tại sao bong bóng lại rơi xuống? (1) Bong bóng xà phòng chịu tác dụng của hai lực chính: trọng lực P hướng thẳng đứng xuống dưới (không đổi) và lực đẩy Acsimet của không khí $F_{A}$ hướng thẳng đứng lên trên (2) Lúc đầu, khối khí trong bong bóng xà phòng có nhiệt độ cao hơn không khí (hơi thở ra của người có nhiệt độ 37$^{o}$C) và $F_{A}$ \\> P, làm cho bong bóng bay lên (3) Sau đó, bong bóng xà phòng giảm nhiệt độ do tỏa nhiệt lượng ra không khí và thu nhỏ thể tích bong bóng lại nên $F_{A}$ nhỏ dần đi, còn P không đổi. Đến một lúc nào đó thì $F_{A}$ \\< P, kết quả là tốc độ đi lên của bong bóng giảm dần rồi từ từ rơi xuống</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">(1) Đúng: bong bóng chịu trọng lực $P$ hướng xuống và lực đẩy Archimedes $F_A$ của không khí hướng lên.</p><p class=\"text-base leading-relaxed my-2\">(2) Đúng: khí thở ra ($37^\\circ$C) nóng hơn không khí nên khối lượng riêng nhỏ hơn không khí xung quanh, $F_A \\gt P$ nên bong bóng bay lên.</p><p class=\"text-base leading-relaxed my-2\">(3) Đúng: khí trong bong bóng tỏa nhiệt, nhiệt độ giảm, thể tích thu nhỏ nên $F_A = \\rho_{kk} g V$ giảm dần, còn $P$ không đổi; đến lúc $F_A \\lt P$ thì bong bóng rơi xuống.</p><p class=\"text-base leading-relaxed my-2\">Vậy cả ba nhận định đều đúng.</p>","options":["(1)sai; (2), (3)đúng","(1) đúng; (2), (3) sai","(1), (2) và (3) sai","(1), (2) và (3) đúng \n<strong>II. Quá trình đẳng tích</strong>"],"answer":3}$q$::jsonb, 212, $q$Động năng trung bình phân tử và nhiệt độ$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Vận dụng phương trình trạng thái","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quá trình đẳng tích là quá trình biến đổi trạng thái của lượng khí xác định khi</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Quá trình đẳng tích là quá trình biến đổi trạng thái của một lượng khí xác định khi thể tích không đổi. Nhiệt độ không đổi là đẳng nhiệt, áp suất không đổi là đẳng áp.</p>","options":["thể tích không đổi.","nhiệt độ không đổi.","áp suất không đổi.","thể tích thay đổi."],"answer":0}$q$::jsonb, 209, $q$Vận dụng phương trình trạng thái$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Vận dụng phương trình trạng thái","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn phát biểu sai khi nói về quá trình đẳng tích của một lượng khí nhất định?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đẳng tích (định luật Charles): $\\dfrac{p}{T} = \\text{const}$, $p$ tỉ lệ thuận với $T$ tuyệt đối, đồ thị $(p, T)$ là đường thẳng (kéo dài qua gốc tọa độ). Các phát biểu B, C, D đúng.</p><p class=\"text-base leading-relaxed my-2\">Tích $pV = \\text{const}$ là đặc trưng của quá trình đẳng nhiệt, không phải đẳng tích. Vậy A sai.</p>","options":["Tích của áp suất và thể tích là một hằng số.","Thương số của áp suất và nhiệt độ là một hằng số.","Áp suất tỉ lệ thuận với nhiệt độ tuyệt đối.","Đồ thị mối liên hệ giữa áp suất và nhiệt độ là một đường thẳng."],"answer":0}$q$::jsonb, 209, $q$Vận dụng phương trình trạng thái$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Vận dụng phương trình trạng thái","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy chọn câu đúng. Khi làm nóng một lượng khí có thể tích không đổi thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Lượng khí có thể tích không đổi nên số phân tử $N$ và $V$ không đổi, do đó số phân tử trong một đơn vị thể tích $n = \\dfrac{N}{V}$ không đổi.</p><p class=\"text-base leading-relaxed my-2\">Khi làm nóng, áp suất tăng (tỉ lệ thuận với $T$), nên A sai; C, D sai vì $n$ không phụ thuộc nhiệt độ ở đây.</p>","options":["áp suất khí không đổi.","số phân tử trong đơn vị thể tích không đổi.","số phân tử trong đơn vị thể tích tăng tỉ lệ thuận với nhiệt độ.","số phân tử trong đơn vị thể tích giảm tỉ lệ nghịch với nhiệt độ."],"answer":1}$q$::jsonb, 209, $q$Vận dụng phương trình trạng thái$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Vận dụng phương trình trạng thái","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Đốt nóng một lượng khí chứa trong một bình kín gần như không nở vì nhiệt sao cho nhiệt độ tuyệt đối của khí tăng lên 1,5 lần. Khi đó áp suất của khí trong bình</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Bình kín gần như không nở nên thể tích không đổi, áp dụng định luật Charles: $\\dfrac{p_1}{T_1} = \\dfrac{p_2}{T_2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{p_2}{p_1} = \\dfrac{T_2}{T_1} = 1{,}5$</p><p class=\"text-base leading-relaxed my-2\">Vậy áp suất tăng lên 1,5 lần.</p>","options":["tăng lên 3 lần.","giảm đi 3 lần.","tăng lên 1,5 lần.","giảm đi 1,5 lần."],"answer":2}$q$::jsonb, 209, $q$Vận dụng phương trình trạng thái$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Vận dụng phương trình trạng thái","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phương trình trạng thái khí lí tưởng cho biết mối liên hệ nào sau đây:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phương trình trạng thái của khí lí tưởng: $\\dfrac{pV}{T} = \\text{const}$ (hay $\\dfrac{p_1V_1}{T_1} = \\dfrac{p_2V_2}{T_2}$).</p><p class=\"text-base leading-relaxed my-2\">Vậy nó cho biết mối liên hệ giữa cả ba thông số: nhiệt độ, thể tích và áp suất.</p>","options":["nhiệt độ và áp suất","nhiệt độ và thể tích","thể tích và áp suất","nhiệt độ, thể tích và áp suất"],"answer":3}$q$::jsonb, 209, $q$Vận dụng phương trình trạng thái$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Đọc đồ thị các đẳng quá trình","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hãy dùng đồ thị p − V để tìm xem dãy các quá trình nối tiếp nào có thể khép kín thành một chu trình?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chu trình khép kín khi trạng thái cuối trùng trạng thái đầu. Xét trên đồ thị $p - V$ với trạng thái đầu $(p_1, V_1)$.</p><p class=\"text-base leading-relaxed my-2\">C: dãn đẳng nhiệt tới $(p_2, V_2)$ với $V_2 \\gt V_1$, $p_2 \\lt p_1$; nén đẳng áp ở $p_2$ về thể tích $V_1$; đun nóng đẳng tích ở $V_1$ làm $p$ tăng từ $p_2$ lên $p_1$. Trạng thái cuối trùng trạng thái đầu nên khép kín.</p><p class=\"text-base leading-relaxed my-2\">A, B: thể tích chỉ tăng hoặc không đổi qua các giai đoạn nên không thể quay về thể tích ban đầu. D: nén đẳng nhiệt làm $p$ tăng cao hơn $p_1$, sau đó đun nóng đẳng tích chỉ làm $p$ tăng thêm nên không về được $p_1$.</p>","options":["Dãn đẳng áp, dãn đẳng nhiệt, làm lạnh đẳng tích.","Đun nóng đẳng tích, dãn đẳng nhiệt, dãn đẳng áp.","Dãn đẳng nhiệt, nén đẳng áp, đun nóng đẳng tích.","Dãn đẳng áp, nén đẳng nhiệt, đun nóng đẳng tích.\n<strong>II. Phương trình Clapeyron</strong>"],"answer":2}$q$::jsonb, 208, $q$Đọc đồ thị các đẳng quá trình$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Mol, số Avogadro và lượng chất khí","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Ở điều kiện tiêu chuẩn (nhiệt độ 0$^{o}$C và áp suất là 1 atm) thì 1 mol của bất kì chất khí nào đều chiếm 1 thể tích là:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Ở điều kiện tiêu chuẩn ($0^\\circ$C, 1 atm), thể tích 1 mol của mọi chất khí là $22{,}4$ lít. Kiểm tra: $V = \\dfrac{nRT}{p} = \\dfrac{1\\cdot 8{,}31\\cdot 273}{1{,}013\\cdot 10^5} \\approx 0{,}0224\\ \\text{m}^3 = 22{,}4$ lít.</p>","options":["2,24 lít","22,4 lít","2,4 lít","24 lít"],"answer":1}$q$::jsonb, 205, $q$Mol, số Avogadro và lượng chất khí$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Phương trình Clapeyron – Mendeleev","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Nếu áp suất khí đo bằng đơn vị Pa(N/m$^{2}$), thể tích đo bằng đơn vị m$^{3}$, nhiệt độ tuyệt đối có đơn vị K thì hằng số chất khí có giá trị:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi $p$ tính bằng Pa, $V$ bằng $\\text{m}^3$, $T$ bằng K thì hằng số khí $R = 8{,}31\\ \\text{J/(mol.K)}$.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $0{,}082$ ứng với $p$ tính bằng atm và $V$ bằng lít.</p>","options":["R = 8,31 J/mol.K.","R = 0,082 J/mol. K .","R = 6,02 J/mol.K.","R = 22,4 J/mol. K."],"answer":0}$q$::jsonb, 210, $q$Phương trình Clapeyron – Mendeleev$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Phương trình Clapeyron – Mendeleev","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phương trình Cla-pê-rôn - Men-đê-lê-ép $pV = \\frac{m}{M}RT$ so với phương trình trạng thái $\\frac{pV}{T} = const$</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Phương trình Clapeyron - Mendeleev $pV = \\dfrac{m}{M}RT$ chứa thêm khối lượng $m$, khối lượng mol $M$ và hằng số $R$, nên cho nhiều thông tin hơn (tính được khối lượng, số mol khí) so với $\\dfrac{pV}{T} = \\text{const}$ chỉ dùng cho một lượng khí xác định.</p><p class=\"text-base leading-relaxed my-2\">Hai phương trình đều áp dụng cho khí lí tưởng nên không thể nói bên nào chính xác hơn hay đúng hơn.</p>","options":["chứa nhiều thông tin hơn","chặt chẽ hơn","chính xác hơn","đúng hơn"],"answer":0}$q$::jsonb, 210, $q$Phương trình Clapeyron – Mendeleev$q$)) as v(q, tid, tname)
